<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Company,Employee,LeavePolicy,LeaveRequest,PayrollRun,Payslip,JobTitle,AttendanceRecord}; use App\Services\{AuditLogger,AuthorizationService,HrPayrollService}; use App\Support\TenantContext; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
final class HrController {
    public function employees(Request $r){$t=app(TenantContext::class)->id();abort_unless(app(AuthorizationService::class)->allows($r->user(),$t,'hr.manage'),403);$q=Employee::where('tenant_id',$t)->with(['contracts','salaryAssignments'])->when($r->filled('search'),fn($q)=>$q->where('legal_name','ilike','%'.$r->string('search').'%'))->orderBy('legal_name');return response()->json(['data'=>$q->paginate(min($r->integer('per_page',25),100))]);}
    public function storeEmployee(Request $r,AuthorizationService $auth,AuditLogger $audit){$t=app(TenantContext::class)->id();$d=$r->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','department_id'=>'nullable|uuid','job_title_id'=>'nullable|uuid','user_id'=>'nullable|uuid','employee_number'=>'required|alpha_dash|max:50','legal_name'=>'required|string|max:200','preferred_name'=>'nullable|string|max:200','email'=>'nullable|email','phone'=>'nullable|string|max:50','address'=>'nullable|string','date_of_birth'=>'nullable|date','joined_on'=>'required|date']);abort_unless($auth->allows($r->user(),$t,'hr.manage',$d['company_id']),403);abort_unless(Company::where('tenant_id',$t)->whereKey($d['company_id'])->exists(),404);$employee=Employee::create([...$d,'tenant_id'=>$t]);$audit->record($r,'hr.employee.created',$t,$employee);return response()->json(['data'=>$employee],201);}
    public function jobTitles(Request $r){$t=app(TenantContext::class)->id();abort_unless(app(AuthorizationService::class)->allows($r->user(),$t,'hr.manage'),403);return response()->json(['data'=>JobTitle::where('tenant_id',$t)->orderBy('name')->paginate(50)]);}
    public function leave(Request $r,HrPayrollService $hr,AuthorizationService $auth){$t=app(TenantContext::class)->id();$d=$r->validate(['employee_id'=>'required|uuid','leave_policy_id'=>'required|uuid','starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on','days'=>'required|numeric|gt:0','reason'=>'nullable|string']);$employee=Employee::where('tenant_id',$t)->whereKey($d['employee_id'])->firstOrFail();abort_unless($auth->allows($r->user(),$t,'hr.manage',$employee->company_id),403);return response()->json(['data'=>$hr->requestLeave([...$d,'tenant_id'=>$t])],201);}
    public function approveLeave(Request $r,LeaveRequest $leaveRequest,HrPayrollService $hr,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($leaveRequest->tenant_id===$t,404);$employee=Employee::whereKey($leaveRequest->employee_id)->firstOrFail();abort_unless($auth->allows($r->user(),$t,'hr.approve',$employee->company_id),403);return response()->json(['data'=>$hr->approveLeave($leaveRequest,$r->user()->id)]);}
    public function attendance(Request $r,AuthorizationService $auth){$t=app(TenantContext::class)->id();$d=$r->validate(['employee_id'=>'required|uuid','work_date'=>'required|date','clock_in'=>'nullable|date','clock_out'=>'nullable|date','worked_hours'=>'nullable|numeric|min:0']);$employee=Employee::where('tenant_id',$t)->whereKey($d['employee_id'])->firstOrFail();abort_unless($auth->allows($r->user(),$t,'hr.manage',$employee->company_id),403);return response()->json(['data'=>AttendanceRecord::updateOrCreate(['employee_id'=>$employee->id,'work_date'=>$d['work_date']],['tenant_id'=>$t,'clock_in'=>$d['clock_in']??null,'clock_out'=>$d['clock_out']??null,'worked_hours'=>$d['worked_hours']??0,'state'=>'closed'])]);}
    public function payroll(Request $r){$t=app(TenantContext::class)->id();abort_unless(app(AuthorizationService::class)->allows($r->user(),$t,'payroll.manage'),403);return response()->json(['data'=>PayrollRun::where('tenant_id',$t)->with('items')->latest()->paginate(25)]);}
    public function createPayroll(Request $r,HrPayrollService $hr,AuthorizationService $auth){$t=app(TenantContext::class)->id();$d=$r->validate(['company_id'=>'required|uuid','name'=>'required|string|max:150','period_starts_on'=>'required|date','period_ends_on'=>'required|date|after_or_equal:period_starts_on','idempotency_key'=>'required|string|max:100']);abort_unless($auth->allows($r->user(),$t,'payroll.manage',$d['company_id']),403);abort_unless(Company::where('tenant_id',$t)->whereKey($d['company_id'])->exists(),404);return response()->json(['data'=>$hr->createPayroll([...$d,'tenant_id'=>$t,'created_by'=>$r->user()->id])],201);}
    public function transition(Request $r,PayrollRun $run,HrPayrollService $hr,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($run->tenant_id===$t,404);$d=$r->validate(['state'=>'required|in:review,approved,finalized']);$permission=$d['state']==='approved'?'payroll.approve':'payroll.manage';abort_unless($auth->allows($r->user(),$t,$permission,$run->company_id),403);$result=$hr->transition($run,$d['state'],$r->user()->id);if($d['state']==='finalized')event(new \App\Events\PayrollFinalizedForAccounting($t,$run->id,$run->company_id));return response()->json(['data'=>$result]);}
    public function payslip(Request $r,Payslip $payslip,AuthorizationService $auth){$t=app(TenantContext::class)->id();abort_unless($payslip->tenant_id===$t,404);$item=$payslip->payrollItem()->with('employee')->firstOrFail();abort_unless($auth->allows($r->user(),$t,'payroll.view',$item->employee->company_id)||$item->employee->user_id===$r->user()->id,403);return response()->json(['data'=>$payslip->load('payrollItem')]);}
}
